   )
   -----------------------------------------------------------------
   begin
      if (clk'event and clk = '1') then
         if (reset = '1') then
            current_state <= s_reset;
            -- Default Reset Values
            irq <= '0';
            reg01 <= (others => '0');
            reset_rtxflag <= '0';
            reset_rxflag <= '0';
            reset_txflag <= '0';
            scl_int <= '1';
            sda_int <= '1';
         elsif (en = '1') then
            current_state <= next_state;
            -- Default Assignment To Internals
            irq <= '0';
            reset_rtxflag <= '0';
            reset_rxflag <= '0';
            reset_txflag <= '0';

            -- Combined Actions
            case current_state is
               when s_reset => 
                  if (txflag = '1' or rxflag = '1') then 
                     sda_int <= '0';
                     txreg <= reg03(6 downto 0) & rxflag;
                     rdcnt <=(others => '0');
                     rd_length <= reg02;
