                  scl_int <= '0';
               when s_start1 => 
                  sda_int <= txreg(7);
                  txreg <= txreg(txreg'left-1 downto 0) & '1';
                  cnt <= (others => '0');
               when s_tx0 => 
                  scl_int <= '1';
               when s_tx2 => 
                  scl_int <= '0';
                  rxreg <= rxreg(rxreg'left-1 downto 0) & sda_i;
               when s_tx3 => 
                  if (cnt /= 7) then 
                     cnt <= cnt+1;
                     sda_int <= txreg(7);
                     txreg <= txreg(txreg'left-1 downto 0) & '1';
                  else
                     cnt <= cnt+1;
                     if rdcnt = 0 or rdcnt = rd_length then
                        sda_int <= '1';
                     else
                        sda_int <= '0';
                     end if;
                     if rxflag = '1' then
                        txreg <= (others => '1');
                     else
                        txreg <= reg00;
                     end if;
                  end if;
               when s_ack0 => 
                  scl_int <= '1';
               when s_ack2 => 
                  scl_int <= '0';
               when s_ack3 => 
                  if (rtxflag = '1') then 
                     reset_rtxflag <= '1';
                     sda_int <= '1';
                  elsif (txflag = '1' or ( rxflag = '1' and rdcnt /= rd_length)) then 
                     if txflag = '0' then
                         rdcnt <= rdcnt+1;
                     end if;
                     reset_txflag <= '1';
                     sda_int <= txreg(7);
                     txreg <= txreg(txreg'left-1 downto 0) & '1';
                     if (rdcnt /= 0) and rxflag = '1' then
                        reg01 <= rxreg;
                        irq <= '1';
                     end if;
                  else
                     sda_int <= '0';
                     reset_rxflag <= '1';
                     if rxflag = '1' then
                        reg01 <= rxreg;
                     end if;
                     txreg <= X"FF";
                  end if;
               when s_stop0 => 
                  scl_int <= '1';
               when s_stop1 => 
                  sda_int <= '1';
                  irq <= '1';
               when s0 => 
                  scl_int <= '1';
               when s1 => 
