            elsif (txflag = '1' or ( rxflag = '1' and rdcnt /= rd_length)) then 
               next_state <= s_tx0;
            else
               next_state <= s_stop0;
            end if;
         when s_stop0 => 
            next_state <= s_stop1;
         when s_stop1 => 
            next_state <= s_wait0;
         when s0 => 
            next_state <= s1;
         when s1 => 
            next_state <= s_start0;
         when s_wait0 => 
            next_state <= s_wait1;
         when s_wait1 => 
            next_state <= s_wait2;
         when s_wait2 => 
            next_state <= s_wait3;
         when s_wait3 => 
            next_state <= s_reset;
         when others =>
            next_state <= s_reset;
      end case;
   end process nextstate_proc;
 
   -----------------------------------------------------------------
   output_proc : process ( 
      current_state
   )
   -----------------------------------------------------------------
   begin
      -- Default Assignment To Internals
      trig <= '0';

      -- Combined Actions
      case current_state is
         when s_start1 => 
            trig <= '1';
         when others =>
            null;
      end case;
   end process output_proc;
 
   -- Concurrent Statements
   --- register ---
   process(clk)
     variable bus_we_q: std_logic;
    variable reset_txflag_q: std_logic;
    variable reset_rxflag_q: std_logic;
   begin
